from __future__ import annotations

from html import escape as e
from pathlib import Path

from .util import read_json


def write_report(directory: Path):
    state = read_json(directory / "run.json")
    story = read_json(directory / "storyboard.json") if (directory / "storyboard.json").exists() else None
    ok = state["code_status"] == "passed"
    title = "Your feature. Brought forward." if ok else "This repair needs a review."
    checks = state.get("checks", [])
    final = [c for c in checks if c["label"] == "final"]
    test_count = next((c["test_count"] for c in final if c["kind"] == "suite"), None)
    subtitle = story["title"] if story else state.get("error", "Run evidence")
    branch = state.get("branch", "Not created")
    rows = "".join(f'<tr><td><span class="status {"pass" if c["passed"] else "fail"}">{"PASS" if c["passed"] else "FAIL"}</span></td>'
                   f'<td><a href="checks/{e(c["id"])}.json">{e(c["label"])} / {e(c["kind"])}</a></td>'
                   f'<td class="mono">{e(c["sha"][:8])}</td><td>{c["seconds"]:.2f}s</td>'
                   f'<td><a href="checks/{e(c["id"])}.log">Open log ↗</a></td></tr>' for c in checks)
    scenes = "".join(f'<article class="scene"><span class="scene-num">0{i+1}</span><div><h3>{e(s["title"])}</h3>'
                     f'<p>{e(s["caption"])}</p><div class="refs">{e(" · ".join(s["evidence_ids"]))}</div></div></article>'
                     for i, s in enumerate(story["scenes"])) if story else '<p>No explanation was generated.</p>'
    diffpath = directory / "patches/candidate.diff"
    diff = diffpath.read_text() if diffpath.exists() else "No validated candidate diff."
    diff_html = "\n".join(f'<span class="{"added" if line.startswith("+") else "removed" if line.startswith("-") else "context"}">{e(line)}</span>' for line in diff.splitlines())
    log = (directory / "events.jsonl").read_text() if (directory / "events.jsonl").exists() else ""
    video = ('<video controls preload="metadata" poster="poster.png"><source src="video.mp4" type="video/mp4"></video>'
             if state.get("video_status") == "rendered" else
             f'<div class="video-empty"><strong>Explanation transcript</strong><p>Video: {e(state.get("video_status", "pending"))}</p><p>{e(state.get("video_error", ""))}</p></div>')
    mode_note = "Trusted local execution · not an OS sandbox" if state.get("executor") == "local" else "Container execution · tests have no network"
    note = '<div class="notice">The mechanical-control run is a scripted import-only comparison, separate from the agent’s repair.</div>' if any(c["label"] == "mechanical-control" for c in checks) else ""
    error = f'<div class="notice error">{e(state["error"])}</div>' if state.get("error") else ""
    pr_link = f'<a class="button" href="{e(state["pr_url"])}">Open draft PR ↗</a>' if state.get("pr_url") else ""
    html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Autorebaser — Run review</title><style>
:root{--ink:#202722;--muted:#667169;--paper:#f4f5f0;--line:#dce2d7;--lime:#dcf37b;--green:#235a3c;--red:#a94237}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button{font:inherit;cursor:pointer}.shell{display:grid;grid-template-columns:228px 1fr;min-height:100vh}aside{position:sticky;top:0;height:100vh;padding:34px 23px;background:#202c26;color:#f1f5ec;display:flex;flex-direction:column}.brand{font-size:21px;font-weight:700;letter-spacing:-.8px}.mark{display:inline-grid;place-items:center;background:var(--lime);color:#253222;border-radius:8px;width:32px;height:32px;margin-right:8px}.side-label{font-size:10px;letter-spacing:1.7px;color:#9eafa2;margin:48px 0 15px}.nav{border:0;width:100%;text-align:left;padding:11px 13px;border-radius:7px;background:none;color:#becdc2;margin:3px 0}.nav.active{color:#20301f;background:var(--lime);font-weight:650}.side-bottom{margin-top:auto;color:#a8b9ac;font-size:12px;border-top:1px solid #405046;padding-top:21px}.side-bottom b{display:block;color:#edf4e8;margin-bottom:7px}.main{padding:28px 48px 64px;max-width:1550px;width:100%;margin:auto}.topbar{display:flex;justify-content:space-between;gap:15px;color:var(--muted);font-size:12px;border-bottom:1px solid var(--line);padding-bottom:22px}.mono{font-family:ui-monospace,SFMono-Regular,monospace;font-size:12px}.pill{display:inline-block;border:1px solid var(--line);padding:5px 11px;border-radius:20px;background:#fafbf7}.eyebrow{font-size:11px;letter-spacing:1.5px;color:var(--green);font-weight:700;margin:34px 0 8px}h1{font-size:clamp(32px,3.8vw,52px);line-height:1.1;letter-spacing:-2.2px;margin:10px 0 15px;max-width:850px}h2{font-size:21px;letter-spacing:-.5px;margin:0}h3{font-size:15px;margin:0 0 7px}.subtitle{color:var(--muted);font-size:16px;max-width:830px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}.metric{background:#fcfdf8;border:1px solid var(--line);padding:17px 20px;border-radius:10px}.metric label{display:block;font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px}.metric strong{display:block;font-size:26px;letter-spacing:-1px;margin-top:5px}.metric small{font-size:12px;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);gap:22px}.panel{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#fcfdf8;margin-bottom:23px}.panel-head{display:flex;align-items:center;justify-content:space-between;padding:21px 24px;border-bottom:1px solid var(--line)}.panel-body{padding:23px}.tag{font-size:10px;letter-spacing:1px;border-radius:4px;padding:4px 8px;background:#e9efdf;color:#466444}video{display:block;width:100%;aspect-ratio:16/9;background:#111d1b}.video-empty{min-height:280px;background:#172721;color:#e3ecd9;display:grid;place-content:center;padding:30px}.video-caption{padding:15px 23px;color:var(--muted);font-size:12px}.scene{display:flex;gap:15px;padding:18px 23px;border-bottom:1px solid #e8ece2}.scene:last-child{border:0}.scene-num{color:var(--green);font:12px ui-monospace,monospace;padding-top:3px}.scene p{margin:0;color:var(--muted);font-size:13px}.refs{font:10px/1.7 ui-monospace,monospace;color:#829077;margin-top:10px}.status{font:10px ui-monospace,monospace;letter-spacing:.7px;padding:5px 8px;border-radius:4px}.pass{background:#e4f0df;color:var(--green)}.fail{background:#f7e7df;color:var(--red)}table{border-collapse:collapse;width:100%;text-align:left;font-size:13px}td,th{padding:14px 20px;border-bottom:1px solid #e8ece2}th{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--muted);font-weight:500}.notice{margin:12px 0 23px;color:var(--muted);font-size:12px;padding:13px 17px;background:#e9eddf;border-radius:6px}.notice.error{background:#f8e6dd;color:#904435;white-space:pre-wrap}.graph{padding:23px;background:#eef2e6}.track{display:flex;align-items:center;gap:9px;margin:9px 0;font-size:12px}.node{padding:7px 12px;background:#fff;border:1px solid #d4deca;border-radius:6px}.node.target{background:#dceee9;color:#275e56}.node.feature{background:#ece4f5;color:#654d89}.node.candidate{background:var(--lime);color:#304b21}.arrow{color:#8d9b82}.section[hidden]{display:none}pre{margin:0;white-space:pre-wrap;word-break:break-word;overflow:auto;padding:25px;font:12px/1.65 ui-monospace,SFMono-Regular,monospace;max-height:700px;background:#19261f;color:#b9c8b9}.added{color:#c4eda7}.removed{color:#f1ada2}.context{color:#b9c8b9}.button{display:inline-block;background:var(--ink);color:#fff;border:0;border-radius:6px;padding:9px 13px;font-size:12px}.footer{margin-top:26px;color:var(--muted);font-size:11px;display:flex;justify-content:space-between;gap:12px}.fact{margin:0 0 18px}.fact label{display:block;color:var(--muted);font-size:11px;margin-bottom:5px}.break{overflow-wrap:anywhere}.callout{font-size:15px;line-height:1.7;color:#435445;border-left:3px solid #bfd960;padding-left:18px}.artifact-links{display:flex;gap:18px;flex-wrap:wrap;margin-top:20px;font-size:12px}@media(max-width:1000px){.shell{grid-template-columns:180px 1fr}.main{padding:25px}.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.shell{display:block}aside{position:relative;height:auto;padding:16px}.side-label,.side-bottom{display:none}aside nav{display:flex;margin-top:12px}.nav{width:auto;font-size:12px}h1{letter-spacing:-1px}.topbar{flex-wrap:wrap}.main{padding:20px}.metrics{gap:8px}.metric{padding:12px}td,th{padding:10px 8px;font-size:11px}}
</style></head><body><div class="shell"><aside><a class="brand" href="review.html"><span class="mark">↗</span>autorebaser</a><div class="side-label">WORKSPACE / RUN REVIEW</div><nav><button class="nav active" data-tab="overview">◉ &nbsp; Overview</button><button class="nav" data-tab="evidence">✓ &nbsp; Evidence</button><button class="nav" data-tab="changes">± &nbsp; Changes</button><button class="nav" data-tab="activity">≡ &nbsp; Activity</button></nav><div class="side-bottom"><b>Understand the change.</b>Keep the feature.<br>Powered by GPT-6 Astra<br><br>Manual trigger · Human review</div></aside><main class="main">
'''
    html += f'<div class="topbar"><span>PROJECT &nbsp;/&nbsp; <b>AUTOREBASER</b> &nbsp;/&nbsp; RUN {e(state["run_id"])}</span><span>{pr_link} <span class="pill">{e(state["code_status"].replace("_", " "))}</span></span></div>'
    html += f'<div class="eyebrow">REBASE / VERIFY / EXPLAIN</div><h1>{title}</h1><p class="subtitle">{e(subtitle)}</p>{error}'
    html += f'<div class="metrics"><div class="metric"><label>Required tests</label><strong>{test_count if test_count is not None else "—"}</strong><small>on the final candidate</small></div><div class="metric"><label>Repair proposals</label><strong>{len(state.get("repairs", []))}</strong><small>{e(state.get("provider", "astra"))} · gpt-6-astra</small></div><div class="metric"><label>Run time</label><strong>{state.get("seconds", 0):.0f}s</strong><small>including checks and render</small></div><div class="metric"><label>Candidate</label><strong class="mono" style="font-size:21px">{e(state.get("candidate", "pending")[:8])}</strong><small>{"fresh checkout verified" if ok else "review required"}</small></div></div>'
    html += f'<section class="section" id="overview"><div class="grid"><div><div class="panel"><div class="panel-head"><h2>The change, explained</h2><span class="tag">MANIM / {e(state.get("story_status", "pending").upper())}</span></div>{video}<div class="video-caption">Generated from this run’s recorded evidence. Causal explanations are model interpretations.</div></div><div class="panel"><div class="panel-head"><h2>Two histories. One working feature.</h2></div><div class="graph"><div class="track"><span class="node">Base {e(state.get("base", "")[:7])}</span><span class="arrow">→</span><span class="node target">Target {e(state.get("target", "")[:7])}</span><span class="arrow">→</span><span class="node candidate">Candidate {e(state.get("candidate", "")[:7])}</span></div><div class="track"><span class="arrow">└────────</span><span class="node feature">Feature {e(state.get("source", "")[:7])}</span><span class="arrow">↗ replayed + adapted</span></div></div></div></div><div class="panel"><div class="panel-head"><h2>Chapter notes</h2><span class="tag">4 SCENES</span></div>{scenes}</div></div>{note}</section>'
    html += f'<section class="section" id="evidence" hidden><div class="panel"><div class="panel-head"><h2>Checks you can inspect</h2><a class="button" href="evidence.json">Evidence JSON ↗</a></div><table><thead><tr><th>Result</th><th>Check</th><th>Commit</th><th>Time</th><th>Evidence</th></tr></thead><tbody>{rows}</tbody></table></div>{note}<div class="notice">{e(mode_note)}. Passing checks establish the recorded behavior on these inputs; they do not establish universal correctness.</div><div class="artifact-links"><a href="environments.json">Dependency environments ↗</a><a href="commits.json">Commit mapping ↗</a><a href="model-calls.json">Model calls ↗</a></div></section>'
    html += f'<section class="section" id="changes" hidden><div class="panel"><div class="panel-head"><h2>Candidate diff</h2><a class="button" href="patches/range-diff.txt">Compare commit series ↗</a></div><pre>{diff_html}</pre></div><div class="artifact-links"><a href="patches/upstream.diff">Upstream changes ↗</a><a href="patches/feature.diff">Original feature ↗</a><a href="patches/repair.diff">Repair only ↗</a></div></section>'
    html += f'<section class="section" id="activity" hidden><div class="panel"><div class="panel-head"><h2>Recorded run activity</h2><a href="run.json">Run manifest ↗</a></div><pre>{e(log)}</pre></div><p class="mono break">Bot branch: {e(branch)}</p><p class="mono">Publication: {e(state.get("publication_status", "not_requested"))}</p></section>'
    html += f'<footer class="footer"><span>{e(mode_note)}</span><a href="review.md">Read the full Markdown report ↗</a></footer></main></div><script>document.querySelectorAll(".nav").forEach(b=>b.addEventListener("click",()=>{{document.querySelectorAll(".nav").forEach(n=>n.classList.toggle("active",n===b));document.querySelectorAll(".section").forEach(s=>s.hidden=s.id!==b.dataset.tab);}}));</script></body></html>'
    (directory / "review.html").write_text(html)
    md = f"# Autorebaser: {state['code_status']}\n\n{subtitle}\n\n"
    md += f"Source: `{state.get('source', 'unresolved')}`\n\nTarget: `{state.get('target', 'unresolved')}`\n\nCandidate: `{state.get('candidate', 'none')}`\n\n"
    md += "## Adaptations\n\n" + "\n".join(f"- `{c['path']}`: {c['reason']}" for r in state.get("repairs", []) for c in r["changes"])
    md += "\n\n## Checks\n\n| Check | Result | Commit |\n| --- | --- | --- |\n"
    md += "\n".join(f"| {c['id']} | {'PASS' if c['passed'] else 'FAIL'} | `{c['sha'][:8]}` |" for c in checks)
    md += f"\n\n## Review notes\n\n{mode_note}.\n\nVideo: {state.get('video_status')}. Story: {state.get('story_status', 'not generated')}.\n\n"
    if story:
        md += "\n\n".join(f"### {s['title']}\n\n{s['caption']}\n\nEvidence: {', '.join(s['evidence_ids'])}." for s in story["scenes"])
    if note:
        md += "\n\nThe mechanical-control is a scripted comparison, not an agent repair step."
    if state.get("error"):
        md += "\n\nFailure: " + state["error"]
    md += "\n\nChecks support the recorded behavior on tested inputs. Human review remains required.\n"
    (directory / "review.md").write_text(md)
